class Solution {
public:
    void solveSudoku(vector<vector<char>>& board) {
        auto isValid = [&](int r, int c, char ch) -> bool {
            for (int i = 0; i < 9; ++i) {
                if (board[r][i] == ch || board[i][c] == ch) return false;
                int br = 3 * (r / 3) + i / 3;
                int bc = 3 * (c / 3) + i % 3;
                if (board[br][bc] == ch) return false;
            }
            return true;
        };
        auto solve = [&](auto& self) -> bool {
            for (int r = 0; r < 9; ++r) {
                for (int c = 0; c < 9; ++c) {
                    if (board[r][c] == '.') {
                        for (char ch = '1'; ch <= '9'; ++ch) {
                            if (isValid(r, c, ch)) {
                                board[r][c] = ch;
                                if (self(self)) return true;
                                board[r][c] = '.';
                            }
                        }
                        return false;
                    }
                }
            }
            return true;
        };
        solve(solve);
    }
};

class Solution {
    public void solveSudoku(char[][] board) {
        solve(board);
    }
    private boolean solve(char[][] board) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    for (char ch = '1'; ch <= '9'; ch++) {
                        if (isValid(board, r, c, ch)) {
                            board[r][c] = ch;
                            if (solve(board)) return true;
                            board[r][c] = '.';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }
    private boolean isValid(char[][] board, int r, int c, char ch) {
        for (int i = 0; i < 9; i++) {
            if (board[r][i] == ch || board[i][c] == ch) return false;
            int br = 3 * (r / 3) + i / 3;
            int bc = 3 * (c / 3) + i % 3;
            if (board[br][bc] == ch) return false;
        }
        return true;
    }
}

var solveSudoku = function(board) {
    function isValid(r, c, ch) {
        for (let i = 0; i < 9; i++) {
            if (board[r][i] === ch || board[i][c] === ch) return false;
            const br = 3 * Math.floor(r / 3) + Math.floor(i / 3);
            const bc = 3 * Math.floor(c / 3) + (i % 3);
            if (board[br][bc] === ch) return false;
        }
        return true;
    }
    function solve() {
        for (let r = 0; r < 9; r++) {
            for (let c = 0; c < 9; c++) {
                if (board[r][c] === '.') {
                    for (let d = 1; d <= 9; d++) {
                        const ch = String(d);
                        if (isValid(r, c, ch)) {
                            board[r][c] = ch;
                            if (solve()) return true;
                            board[r][c] = '.';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }
    solve();
};
